FoamFile
{
    format      ascii;
    class       dictionary;
    object      controlDict;
}

application     chtMultiRegionFoam;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         20;
deltaT          0.01;

writeControl    adjustableRunTime;
writeInterval   0.1;
purgeWrite      0;
writeFormat     ascii;
writePrecision  8;
writeCompression off;
timeFormat      general;
timePrecision   8;
runTimeModifiable true;

adjustTimeStep  yes;
maxCo           5;
maxDi           20;
maxDeltaT       1;

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvSolution;
}

PIMPLE
{
    nOuterCorrectors          1;
    nEnergyCorrectors         2;
    nNonOrthogonalCorrectors  0;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      topoSetDict;
}

actions
(
    {
        name    solidCells;
        type    cellSet;
        action  new;
        source  cylinderToCell;
        p1      (0 0 -0.003);
        p2      (0 0  0.003);
        radius  0.005001;
    }
    {
        name    solid;
        type    cellZoneSet;
        action  new;
        source  setToCellZone;
        set     solidCells;
    }
);

FoamFile
{
    format      ascii;
    class       dictionary;
    object      regionProperties;
}

regions
(
    fluid (fluid)
    solid (solid)
);

FoamFile
{
    format      ascii;
    class       dictionary;
    object      physicalProperties;
}

thermoType
{
    type            heRhoThermo;
    mixture         pureMixture;
    transport       const;
    thermo          eConst;
    equationOfState rhoConst;
    specie          specie;
    energy          sensibleInternalEnergy;
}

mixture
{
    specie
    {
        molWeight   18.01528;
    }
    equationOfState
    {
        rho         998.19;
    }
    thermodynamics
    {
        Cv          4150;
        Hf          0;
    }
    transport
    {
        mu          1.0005e-3;
        Pr          6.31;
    }
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      momentumTransport;
}

simulationType RAS;

RAS
{
    model           kOmegaSST;
    turbulence      on;
    printCoeffs     on;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      thermophysicalTransport;
}

simulationType RAS;

RAS
{
    model           eddyDiffusivity;
    Prt             0.85;
}

FoamFile
{
    format      ascii;
    class       uniformDimensionedVectorField;
    object      g;
}

dimensions      [0 1 -2 0 0 0 0];
value           (0 0 0);

FoamFile
{
    format      ascii;
    class       dictionary;
    object      radiationProperties;
}

radiationModel  none;

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvModels;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvConstraints;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      physicalProperties;
}

thermoType
{
    type            heSolidThermo;
    mixture         pureMixture;
    transport       constIsoSolid;
    thermo          eConst;
    equationOfState rhoConst;
    specie          specie;
    energy          sensibleInternalEnergy;
}

mixture
{
    specie
    {
        molWeight   63.546;
    }
    equationOfState
    {
        rho         8940;
    }
    thermodynamics
    {
        Cv          385;
        Hf          0;
    }
    transport
    {
        kappa       380;
    }
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      radiationProperties;
}

radiationModel  none;

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvModels;
}

volumetricHeating
{
    type            heatSource;
    selectionMode   all;
    q               5e7;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvConstraints;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvSchemes;
}

ddtSchemes
{
    default         Euler;
}

gradSchemes
{
    default         Gauss linear;
    grad(U)         cellLimited Gauss linear 1;
}

divSchemes
{
    default                             none;
    div(phi,U)                          bounded Gauss linearUpwind grad(U);
    div(phi,e)                          bounded Gauss upwind;
    div(phi,h)                          bounded Gauss upwind;
    div(phi,K)                          bounded Gauss upwind;
    div(phi,k)                          bounded Gauss upwind;
    div(phi,omega)                      bounded Gauss upwind;
    "div(phi,(p|rho))"                 Gauss upwind;
    div(((rho*nuEff)*dev2(T(grad(U))))) Gauss linear;
}

laplacianSchemes
{
    default         Gauss linear limited 0.5;
}

interpolationSchemes
{
    default         linear;
}

snGradSchemes
{
    default         limited 0.5;
}

wallDist
{
    method          meshWave;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvSolution;
}

solvers
{
    rho
    {
        solver          diagonal;
    }
    rhoFinal
    {
        solver          diagonal;
    }
    p_rgh
    {
        solver          GAMG;
        tolerance       1e-7;
        relTol          0.05;
        smoother        GaussSeidel;
    }
    p_rghFinal
    {
        $p_rgh;
        tolerance       1e-8;
        relTol          0;
    }
    U
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-7;
        relTol          0.05;
    }
    UFinal
    {
        $U;
        tolerance       1e-8;
        relTol          0;
    }
    "(e|h)"
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-8;
        relTol          0.02;
    }
    "(e|h)Final"
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-9;
        relTol          0;
    }
    "(k|omega)"
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-7;
        relTol          0.05;
    }
    "(k|omega)Final"
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-8;
        relTol          0;
    }
}

PIMPLE
{
    momentumPredictor          yes;
    nCorrectors                2;
    nNonOrthogonalCorrectors   1;
    pRefCell                   0;
    pRefValue                  0;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvSchemes;
}

ddtSchemes
{
    default         Euler;
}

gradSchemes
{
    default         Gauss linear;
}

divSchemes
{
    default         none;
}

laplacianSchemes
{
    default         Gauss linear limited 0.5;
}

interpolationSchemes
{
    default         linear;
}

snGradSchemes
{
    default         limited 0.5;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvSolution;
}

solvers
{
    "(e|h)"
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-9;
        relTol          0.02;
    }
    "(e|h)Final"
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-10;
        relTol          0;
    }
}

PIMPLE
{
    nNonOrthogonalCorrectors 1;
}

FoamFile
{
    format      ascii;
    class       volVectorField;
    object      U;
}

dimensions      [0 1 -1 0 0 0 0];
internalField   uniform (0 0 0);

boundaryField
{
    inlet
    {
        type            fixedValue;
        value           uniform (0.1 0 0);
    }
    outlet
    {
        type            zeroGradient;
    }
    topAndBottom
    {
        type            slip;
    }
    frontAndBack
    {
        type            empty;
    }
    fluid_to_solid
    {
        type            fixedValue;
        value           uniform (0 0 0);
    }
}

FoamFile
{
    format      ascii;
    class       volScalarField;
    object      T;
}

dimensions      [0 0 0 1 0 0 0];
internalField   uniform 297;

boundaryField
{
    inlet
    {
        type            fixedValue;
        value           uniform 297;
    }
    outlet
    {
        type            zeroGradient;
    }
    topAndBottom
    {
        type            zeroGradient;
    }
    frontAndBack
    {
        type            empty;
    }
    fluid_to_solid
    {
        type            compressible::turbulentTemperatureCoupledBaffleMixed;
        Tnbr            T;
        kappaMethod     fluidThermo;
        value           uniform 297;
    }
}

